1:<script lang="ts">
2:  import "../workbench/workbench.css";
3:  import { onDestroy, onMount, untrack, type Snippet } from "svelte";
4:  import type { ChatAdapter } from "../chat/chat-adapter";
5:  import type { ResolvedChatContext } from "../chat/chat-mode";
6:  import { emptyFeedSnapshot, type FeedSnapshot } from "../grpc/plugin-feeds";
7:  import { Runtime, provideRuntime } from "./runtime.svelte";
8:  import { ChatSession } from "./chat-session";
9:  import { provideSession } from "./session-context";
10:  import { providePluginFeeds } from "./plugin-feeds";
11:  let {
12:    adapter,
13:    children,
14:    onCanvas,
15:  }: {
16:    adapter: ChatAdapter;
17:    children: Snippet<[Runtime, ChatSession]>;
18:    onCanvas?: (present: boolean) => void;
19:  } = $props();
20:  const runtime = new Runtime(untrack(() => adapter));
21:  const session = new ChatSession();
22:  const feeds = untrack(() => adapter.pluginFeeds);
23:  let snapshot = $state.raw<FeedSnapshot>(emptyFeedSnapshot());
24:  if (feeds) providePluginFeeds(() => snapshot);
25:  provideRuntime(runtime);
26:  provideSession(session);
27:  session.configure(untrack(() => runtime.snapshot()));
28:  onMount(() => {
29:    if (runtime.adapter.catalogRefreshOnMount) void runtime.refreshProviders();
30:  });
31:  $effect(() => {
32:    session.configure(runtime.snapshot());
33:  });
34:  $effect(() => {
35:    // Track only the verified context, not state changed by the generation request.
36:    if (runtime.chatContext) untrack(() => void runtime.loadInterface());
37:  });
38:  $effect(() => {
39:    onCanvas?.(runtime.canvasSpec !== null);
40:  });
41:  $effect(() => {
42:    if (!feeds) return;
43:    const write = () => {
44:      snapshot = feeds.getSnapshot();
45:    };
46:    write();
47:    const unsubscribe = feeds.subscribe(write);
48:    const release = feeds.acquire();
49:    return () => {
50:      unsubscribe();
51:      release();
52:      snapshot = emptyFeedSnapshot();
53:    };
54:  });
55:  onMount(() => {
56:    const readContext = (adapter as ChatAdapter & { getChatContext?: () => Promise<ResolvedChatContext> }).getChatContext;
57:    if (!readContext) return;
58:    let alive = true;
59:    void readContext().then((context) => {
60:      if (alive) runtime.setChatContext(context);
61:    }).catch((error: unknown) => {
62:      if (alive) runtime.interfaceError = error instanceof Error ? error.message : "The chatbot could not be instigated.";
63:    });
64:    return () => { alive = false; };
65:  });
66:  onDestroy(() => {
67:    session.dispose();
68:    runtime.dispose();
69:  });
